  "Button does nothing? Choose <b>Copy setup instead</b>, run <b>MCP: Open User Configuration</b> from the Command Palette and paste it there. VS Code uses <code>servers</code>, not <code>mcpServers</code>.": "ปุ่มไม่ทำงาน? เลือก <b>คัดลอกการตั้งค่าแทน</b> แล้วรัน <b>MCP: Open User Configuration</b> จาก Command Palette และวางที่นั่น VS Code ใช้ <code>servers</code> ไม่ใช่ <code>mcpServers</code>",
