  "Chat with a model you choose; {mnemo} reads, writes, tags, links, moves and tidies notes with Memora's own tools. It cannot browse the web, run commands, delete for good or change the server. Keys are sealed on this server and never sent to the browser.": "แชตกับโมเดลที่คุณเลือก {mnemo} อ่าน เขียน แท็ก เชื่อม ย้าย และจัดโน้ตด้วยเครื่องมือของ Memora เอง ท่องเว็บ รันคำสั่ง ลบถาวร หรือเปลี่ยนเซิร์ฟเวอร์ไม่ได้ คีย์ถูกเก็บปิดผนึกบนเซิร์ฟเวอร์นี้และไม่ถูกส่งไปยังเบราว์เซอร์",
