  "Choose from many languages in Settings, Appearance, per device. Auto follows your browser.": "เลือกได้หลายภาษาใน การตั้งค่า หน้าตา แยกตามอุปกรณ์ อัตโนมัติ จะตามเบราว์เซอร์ของคุณ",
