  "Claude Desktop (older)": "Claude Desktop (รุ่นเก่า)",
  "Claude and ChatGPT sign in with your Memora account. Nothing to copy.": "Claude และ ChatGPT ลงชื่อเข้าใช้ด้วยบัญชี Memora ของคุณ ไม่ต้องคัดลอกอะไร",
  "Claude models": "โมเดล Claude",
  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Claude ลงชื่อเข้าใช้ผ่าน OAuth จึงไม่ต้องวางคีย์ เมื่อกด อนุญาต จะได้คีย์ของตัวเอง ถ้าไม่ลงชื่อเข้าใช้ ให้เชื่อมต่อเป็น <b>แอปอื่น</b> และส่ง header <code>Authorization: Bearer &lt;key&gt;</code>",
  "Claude, ChatGPT, Cursor and more": "Claude, ChatGPT, Cursor และอื่นๆ",
  "Claude, ChatGPT, Cursor and more, each with its own key": "Claude, ChatGPT, Cursor และอื่น ๆ แต่ละตัวมีคีย์ของตัวเอง",
  "Claude, ChatGPT, Cursor, Codex and others each get their own access, so you can see what each one does.": "Claude, ChatGPT, Cursor, Codex และอื่นๆ ได้สิทธิ์เข้าถึงของตัวเอง คุณจึงเห็นว่าแต่ละตัวทำอะไร",
  "Claude, Cursor, ChatGPT and your own agent share one Memora, reachable from this computer, the local network or the internet": "Claude, Cursor, ChatGPT และเอเจนต์ของคุณใช้ Memora เดียวกัน เข้าถึงได้จากคอมพิวเตอร์เครื่องนี้ เครือข่ายภายใน หรืออินเทอร์เน็ต",
  "Claude, Cursor, ChatGPT and your own scripts read your notes and add to them.": "Claude, Cursor, ChatGPT และสคริปต์ของคุณเองอ่านโน้ตของคุณและเพิ่มเนื้อหาลงไป",
