  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "เอเจนต์แต่ละตัวเป็นของแอปเดียว หากต้องการใช้ Memora ในแอปอื่น ให้สร้างเอเจนต์แยกต่างหาก",
  "Each app gets its own key": "แต่ละแอปมีคีย์ของตัวเอง",
  "Each has a short id that never changes, so names can change freely. Mnemo sets them up, changes their instructions or model, messages, waits for, stops, finishes and removes them, one or all at once, and can let them work in the background. Each card shows Instruction, Activity and Answer.": "แต่ละตัวมีรหัสสั้นที่ไม่เปลี่ยน จึงเปลี่ยนชื่อได้อิสระ Mnemo สร้าง เปลี่ยนคำแนะนำหรือโมเดล ส่งข้อความ รอ หยุด ปิดงาน และลบพวกมัน ทีละตัวหรือทั้งหมดพร้อมกัน และปล่อยให้ทำงานเบื้องหลังได้ การ์ดแต่ละใบแสดงคำสั่ง กิจกรรม และคำตอบ",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "แต่ละประเภทวัดกับพื้นที่ของตัวเอง: ขีดจำกัดถ้าตั้งไว้ ไม่งั้นคือที่ใช้อยู่บวกพื้นที่ดิสก์ว่าง{disk} ขีดจำกัดว่าง: ไม่มี",
