  "Every agent usually starts from zero. {bold} connect each agent once and they all read the same vault and write back to it, so what one learns, the others can use.": "เอเจนต์ส่วนใหญ่เริ่มจากศูนย์ทุกครั้ง {bold} เชื่อมต่อแต่ละเอเจนต์ครั้งเดียว แล้วทุกตัวจะอ่านคลังเดียวกันและเขียนกลับ สิ่งที่ตัวหนึ่งเรียนรู้ ตัวอื่นก็ใช้ได้",
