  "Every board with its lanes and progress. New board sits wherever New note does: the sidebar, Overview, folders, menus, search and the B key.": "ทุกบอร์ดพร้อมเลนและความคืบหน้า “บอร์ดใหม่” อยู่ทุกที่ที่มี “โน้ตใหม่”: แถบด้านข้าง ภาพรวม โฟลเดอร์ เมนู การค้นหา และปุ่ม B",
  "Every browser and agent is disconnected until someone starts Memora again on that machine. This page cannot start it again.": "ทุกเบราว์เซอร์และเอเจนต์จะถูกตัดการเชื่อมต่อจนกว่าจะมีคนเริ่ม Memora บนเครื่องนั้นอีกครั้ง หน้านี้เริ่มใหม่ให้ไม่ได้",
  "Every call shows up live in the brain and Activity": "ทุกการเรียกแสดงสดในสมองและกิจกรรม",
