  "Every connected AI loses all {n} tools at once and can no longer read or change your notes until you turn tools back on here.": "AI ที่เชื่อมต่อทุกตัวจะเสียเครื่องมือทั้ง {n} รายการพร้อมกัน และอ่านหรือแก้ไขโน้ตของคุณไม่ได้อีก จนกว่าคุณจะเปิดเครื่องมือกลับที่นี่",
  "Every connected AI loses it at once. You can turn it back on any time.": "AI ที่เชื่อมต่อทุกตัวจะเสียมันพร้อมกัน เปิดกลับได้ทุกเมื่อ",
