  "Every device on a home or office network, written as address/size: 192.168.1.0/24 covers 192.168.1.0 to 192.168.1.255.": "ทุกอุปกรณ์ในเครือข่ายบ้านหรือสำนักงาน เขียนเป็นที่อยู่/ขนาด: 192.168.1.0/24 ครอบคลุม 192.168.1.0 ถึง 192.168.1.255",
