  "Every note tagged #{tag} ({notes}) gets the new name, inline #tags in the text too.": "ทุกโน้ตที่ติดแท็ก #{tag} ({notes}) จะได้ชื่อใหม่ รวมถึง #tag ในข้อความด้วย",
