  "Get started": "เริ่มต้นใช้งาน",
  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "ทำความรู้จักฉันจากโน้ตของฉัน ดูคลังของฉัน (โน้ตล่าสุด สมุดบันทึก โปรเจกต์ ทุกอย่างเกี่ยวกับฉัน) แล้วเก็บสิ่งที่รู้ด้วย remember_owner: ฉันคือใคร ทำงานอะไร ชอบคำตอบแบบไหน ชอบอะไร เก็บเฉพาะเรื่องสั้นๆ ที่อยู่ได้นาน ห้ามเก็บความลับ จากนั้นบอกฉันสั้นๆ ไม่กี่บรรทัดว่าเก็บอะไรไว้",
  "Gets its own agent key: read and write nodes over MCP": "ได้คีย์เอเจนต์ของตัวเอง: อ่านและเขียนโหนดผ่าน MCP",
