  "GitHub answered HTTP {code}": "GitHub ตอบกลับ HTTP {code}",
  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "ให้ Claude, Cursor หรือแอป MCP ใดก็ได้มีคีย์ของตัวเอง แล้วให้มันบันทึกสิ่งที่รู้เกี่ยวกับคุณอยู่แล้ว",
  "Give a key read-only access, or let it write too.": "ให้คีย์อ่านได้อย่างเดียว หรือให้เขียนได้ด้วย",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "ให้แต่ละแอปหรืออุปกรณ์มีเอเจนต์ของตัวเอง กิจกรรมจะแสดงชัดว่าใครทำอะไร และปิดตัวหนึ่งได้โดยไม่กระทบตัวอื่น",
