  "Images live beside the notes that show them. Choose how large one may be, and see what notes and images take.": "รูปภาพอยู่ข้างโน้ตที่แสดงมัน เลือกว่าใหญ่ได้เท่าไร และดูว่าโน้ตและรูปภาพใช้พื้นที่เท่าไร",
  "Import and export": "นำเข้าและส่งออก",
  "Imported": "นำเข้าแล้ว",
  "In ChatGPT, open <b>Settings → Apps &amp; Connectors → Advanced settings</b> and turn on <b>Developer mode</b>. Then choose <b>Create</b>.": "ใน ChatGPT เปิด <b>Settings → Apps &amp; Connectors → Advanced settings</b> แล้วเปิด <b>Developer mode</b> จากนั้นเลือก <b>Create</b>",
  "In Claude (web or desktop), open <b>Settings → Connectors</b> and choose <b>Add custom connector</b>.": "ใน Claude (เว็บหรือเดสก์ท็อป) เปิด <b>Settings → Connectors</b> แล้วเลือก <b>Add custom connector</b>",
  "In Claude Desktop, open <b>Settings → Developer → Edit Config</b>. On newer versions, pick <b>Claude</b> instead.": "ใน Claude Desktop เปิด <b>Settings → Developer → Edit Config</b> ในเวอร์ชันใหม่ ให้เลือก <b>Claude</b> แทน",
  "In Windsurf, open <b>Settings → Cascade → MCP servers</b> and choose <b>View raw config</b>.": "ใน Windsurf เปิด <b>Settings → Cascade → MCP servers</b> แล้วเลือก <b>View raw config</b>",
