  "It can change notes, but nothing lets it connect.": "แก้ไขโน้ตได้ แต่ไม่มีอะไรให้เชื่อมต่อ",
  "It can search and read your notes, but not change them": "ค้นหาและอ่านโน้ตของคุณได้ แต่แก้ไขไม่ได้",
