  "Look through the project in this folder and save it into Memora: what it is for, how it is built, how to run it, technical decisions, and anything worth remembering. Make one note per topic, in a folder named after the project inside Projects.": "ดูโปรเจกต์ในโฟลเดอร์นี้แล้วบันทึกลง Memora: ใช้ทำอะไร สร้างอย่างไร รันอย่างไร การตัดสินใจทางเทคนิค และสิ่งที่ควรจำ ทำหนึ่งโน้ตต่อหนึ่งหัวข้อ ในโฟลเดอร์ที่ตั้งชื่อตามโปรเจกต์ภายใน Projects",
