  "Meet Mnemo, your notes agent": "รู้จัก Mnemo เอเจนต์โน้ตของคุณ",
  "Memora address (MCP endpoint)": "ที่อยู่ Memora (MCP endpoint)",
  "Memora already uses this folder.": "Memora ใช้โฟลเดอร์นี้อยู่แล้ว",
  "Memora by Codrihub Tech": "Memora โดย Codrihub Tech",
  "Memora can save notes here": "Memora บันทึกโน้ตที่นี่ได้",
  "Memora checks the folder and asks you to confirm before it switches. Nothing is moved or copied, and you can switch back here. Running in Docker? Use a folder mounted into the container.": "Memora จะตรวจโฟลเดอร์และขอให้คุณยืนยันก่อนสลับ ไม่มีอะไรถูกย้ายหรือคัดลอก และสลับกลับที่นี่ได้ ใช้ Docker อยู่หรือ ใช้โฟลเดอร์ที่ mount เข้าคอนเทนเนอร์",
  "Memora could not start.": "Memora เริ่มทำงานไม่ได้",
  "Memora data folder": "โฟลเดอร์ข้อมูล Memora",
  "Memora first checks that the new folder exists (or can be created) and that it can save notes there. If the check fails, nothing changes.": "Memora จะตรวจก่อนว่าโฟลเดอร์ใหม่มีอยู่ (หรือสร้างได้) และบันทึกโน้ตที่นั่นได้ ถ้าตรวจไม่ผ่าน จะไม่มีอะไรเปลี่ยน",
  "Memora first checks that the new folder exists and that it can save notes there. If the check fails, nothing changes.": "Memora จะตรวจก่อนว่าโฟลเดอร์ใหม่มีอยู่และบันทึกโน้ตที่นั่นได้ ถ้าตรวจไม่ผ่าน จะไม่มีอะไรเปลี่ยน",
  "Memora in your language, Mnemo showing its plan as it works, and you choosing what it may use and see.": "Memora ในภาษาของคุณ Mnemo แสดงแผนของมันขณะทำงาน และคุณเลือกได้ว่ามันใช้และเห็นอะไร",
  "Memora is a notes app your AI apps can use too. You write in it, they read and write the same notes, and you can always see what changed.": "Memora เป็นแอปโน้ตที่แอป AI ของคุณใช้ได้ด้วย คุณเขียน พวกมันอ่านและเขียนโน้ตชุดเดียวกัน และคุณเห็นได้เสมอว่ามีอะไรเปลี่ยน",
  "Memora is free and open source": "Memora ฟรีและเป็นโอเพนซอร์ส",
  "Memora is free and open source. A star helps others find it.": "Memora ฟรีและเป็นโอเพนซอร์ส ดาวช่วยให้คนอื่นเจอ",
  "Memora is memory, advanced: built to remember what you and your AI learn, and to remember more the more you use it.": "Memora คือความจำขั้นสูง: สร้างมาเพื่อจำสิ่งที่คุณและ AI เรียนรู้ และจำได้มากขึ้นยิ่งใช้",
  "Memora is restarting": "Memora กำลังรีสตาร์ท",
  "Memora is shut down": "Memora ปิดอยู่",
  "Memora is still empty. Connect an AI app, send it one prompt, and it saves what it knows about you here, as notes you can read, edit and see in the brain.": "Memora ยังว่างอยู่ เชื่อมต่อแอป AI ส่งพรอมต์หนึ่งข้อ แล้วมันจะบันทึกสิ่งที่รู้เกี่ยวกับคุณที่นี่ เป็นโน้ตที่คุณอ่าน แก้ไข และดูในสมองได้",
  "Memora keeps a list of your tags to suggest them while you type. Refresh it if a tag is missing or out of date.": "Memora เก็บรายการแท็กของคุณไว้เพื่อแนะนำขณะพิมพ์ รีเฟรชถ้าแท็กหายหรือล้าสมัย",
  "Memora keeps every version of a note when the vault folder is a git repository. Run {cmd} in the vault folder once (see Configuration, “Version history” in the docs); from then on every change is kept here.": "Memora เก็บทุกเวอร์ชันของโน้ตเมื่อโฟลเดอร์คลังเป็นรีโพซิทอรี git รัน {cmd} ในโฟลเดอร์คลังครั้งหนึ่ง (ดู Configuration, “Version history” ในเอกสาร) จากนั้นทุกการเปลี่ยนแปลงจะเก็บไว้ที่นี่",
  "Memora keeps it in one place:": "Memora เก็บไว้ที่เดียว:",
  "Memora saves every note as a plain Markdown file on the machine it runs on. Nothing is locked in: open the files in any editor, back them up, or keep them in Git.": "Memora เก็บทุกโน้ตเป็นไฟล์ Markdown ธรรมดาบนเครื่องที่รันอยู่ ไม่ถูกล็อกไว้: เปิดไฟล์ด้วยโปรแกรมแก้ไขใดก็ได้ สำรองข้อมูล หรือเก็บใน Git",
  "Memora speaks MCP over streamable HTTP. Apps send the key in the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Memora ใช้ MCP ผ่าน streamable HTTP แอปส่งคีย์ใน header <code>Authorization: Bearer &lt;key&gt;</code>",
  "Memora stops on the machine it runs on. Your notes stay safe on disk.": "Memora หยุดบนเครื่องที่รันอยู่ โน้ตของคุณปลอดภัยบนดิสก์",
  "Memora version": "เวอร์ชัน Memora",
  "Memora v{latest} is available. This server runs v{current}.": "Memora v{latest} พร้อมใช้งาน เซิร์ฟเวอร์นี้รัน v{current}",
  "Memora v{version} is available": "Memora v{version} พร้อมใช้งาน",
  "Memora, open Overview": "Memora เปิดภาพรวม",
  "Memora: a notes vault you host yourself, with an agent that tidies it.": "Memora: คลังโน้ตที่คุณโฮสต์เอง พร้อมเอเจนต์ที่จัดให้เรียบร้อย",
  "Memory used: {used} of {win}": "ความจำที่ใช้: {used} จาก {win}",
  "Mentioned in": "ถูกกล่าวถึงใน",
  "Mentions": "การกล่าวถึง",
  "Menus that fit": "เมนูที่พอดีกับงาน",
  "Menus that fit where you are, an archive you can search, softer progress and due dates, and steps you can tick on the card.": "เมนูที่เหมาะกับที่ที่คุณอยู่ ที่เก็บถาวรที่ค้นหาได้ ความคืบหน้าและวันครบกำหนดที่นุ่มนวลขึ้น และขั้นตอนที่ติ๊กได้บนการ์ด",
  "Menus, tidied": "เมนูที่เป็นระเบียบขึ้น",
