  "Messaged {agent}": "ส่งข้อความถึง {agent}",
  "Messages and the message box line up exactly in every width, the model picker has its own surface, the fleeting chat fits phones, and a question's options never slide away as you tap them.": "ข้อความและช่องพิมพ์ตรงกันพอดีทุกความกว้าง ตัวเลือกโมเดลมีพื้นผิวของตัวเอง แชตชั่วคราวพอดีกับโทรศัพท์ และตัวเลือกของคำถามไม่เลื่อนหนีขณะแตะ",
  "Middle-drag": "ลากด้วยปุ่มกลาง",
  "Midnight": "เที่ยงคืน",
  "Minimap": "แผนที่ย่อ",
  "Minimap: click or drag to move the view": "แผนที่ย่อ: คลิกหรือลากเพื่อเลื่อนมุมมอง",
  "Mist": "หมอก",
  "Mnemo (AI agent)": "Mnemo (เอเจนต์ AI)",
  "Mnemo and agents can do on a board everything you can, over MCP, behind four Kanban permission switches that follow Ask first, Auto and Read only.": "Mnemo และเอเจนต์ทำทุกอย่างบนบอร์ดได้เหมือนคุณผ่าน MCP โดยมีสวิตช์สิทธิ์ Kanban สี่ตัวที่ใช้ ถามก่อน อัตโนมัติ และอ่านอย่างเดียว",
  "Mnemo button hidden. Show it again from More, Show the Mnemo button.": "ซ่อนปุ่ม Mnemo แล้ว แสดงอีกครั้งได้จาก เพิ่มเติม แสดงปุ่ม Mnemo",
  "Mnemo goes on without sub-agents": "Mnemo ทำต่อโดยไม่มีเอเจนต์ย่อย",
  "Mnemo has no model yet: add a provider and its models in Settings, Mnemo": "Mnemo ยังไม่มีโมเดล: เพิ่มผู้ให้บริการและโมเดลใน การตั้งค่า, Mnemo",
  "Mnemo is built into Memora. Connect your own AI key, then ask in plain words: it finds, writes, tags, links and tidies notes for you.": "Mnemo ติดมากับ Memora เชื่อมต่อคีย์ AI ของคุณ แล้วถามด้วยภาษาง่าย ๆ: มันค้นหา เขียน แท็ก เชื่อมโยง และจัดโน้ตให้คุณ",
  "Mnemo is still answering in this chat": "Mnemo ยังตอบอยู่ในแชตนี้",
  "Mnemo is the agent built into Memora. Connect your own AI key and ask in plain words: it keeps your notes in order while your other apps use them.": "Mnemo คือเอเจนต์ที่มาพร้อมใน Memora เชื่อมต่อคีย์ AI ของคุณเองแล้วสั่งด้วยภาษาธรรมดา: มันจัดโน้ตของคุณให้เป็นระเบียบ ขณะที่แอปอื่นๆ ของคุณใช้งานโน้ตเหล่านั้น",
  "Mnemo keeps at most {n} providers; delete one first": "Mnemo เก็บผู้ให้บริการได้สูงสุด {n} ราย ลบหนึ่งรายก่อน",
  "Mnemo knows what is due": "Mnemo รู้ว่ามีอะไรครบกำหนด",
  "Mnemo manages its sub-agents, keeps its plan with the chat, and the chat fits every screen better.": "Mnemo จัดการเอเจนต์ย่อย เก็บแผนไว้กับแชต และแชตพอดีกับทุกหน้าจอมากขึ้น",
  "Mnemo runs its sub-agents": "Mnemo คุมเอเจนต์ย่อย",
  "Mnemo stopped after {n} steps; say \"continue\" to go on.": "Mnemo หยุดหลัง {n} ขั้นตอน พิมพ์ \"ต่อ\" เพื่อไปต่อ",
  "Mnemo's plan, live": "แผนของ Mnemo แบบสด",
  "Mnemo's question sits on its own band, its answers below as rows to tap, as many as the question needs.": "คำถามของ Mnemo อยู่บนแถบของตัวเอง ส่วนคำตอบอยู่ด้านล่างเป็นแถวให้แตะ มากเท่าที่คำถามต้องการ",
  "Mnemo, your notes agent": "Mnemo เอเจนต์โน้ตของคุณ",
