  "Models": "โมเดล",
  "Models for each job": "โมเดลสำหรับแต่ละงาน",
  "Models, API keys and what the notes agent may do": "โมเดล คีย์ API และสิ่งที่เอเจนต์โน้ตทำได้",
  "Models, keys and instructions": "โมเดล คีย์ และคำสั่ง",
  "Money": "การเงิน",
  "Mono": "โมโน",
  "More": "เพิ่มเติม",
  "More actions": "การดำเนินการเพิ่มเติม",
  "More actions for {name}": "การดำเนินการเพิ่มเติมสำหรับ {name}",
  "More cards than the limit of {n}": "การ์ดเกินขีดจำกัด {n} ใบ",
  "More instruction styles": "รูปแบบคำสั่งเพิ่มเติม",
  "More on phones": "เพิ่มเติมบนมือถือ",
  "More: export, all activity": "เพิ่มเติม: ส่งออก กิจกรรมทั้งหมด",
  "More: reload, export": "เพิ่มเติม: โหลดใหม่ ส่งออก",
  "More: rename, move, colour, delete": "เพิ่มเติม: เปลี่ยนชื่อ ย้าย สี ลบ",
  "More: rename, move, pin, delete": "เพิ่มเติม: เปลี่ยนชื่อ ย้าย ปักหมุด ลบ",
  "Most AI apps start each chat from nothing, and each keeps its own memory. With Memora, Claude, Cursor and any other app that speaks MCP read and write the same notes, so what one app learns, the others can use.": "แอป AI ส่วนใหญ่เริ่มทุกแชตจากศูนย์ และแต่ละตัวมีความจำของตัวเอง ด้วย Memora ทั้ง Claude, Cursor และแอปอื่นที่ใช้ MCP ได้ จะอ่านและเขียนโน้ตชุดเดียวกัน สิ่งที่แอปหนึ่งเรียนรู้ แอปอื่นก็ใช้ได้",
  "Most cards in this lane (0 for no limit)": "จำนวนการ์ดสูงสุดในเลนนี้ (0 คือไม่จำกัด)",
  "Most connected": "เชื่อมโยงมากที่สุด",
