  "Not done: Mnemo is in Ask first mode, so changes wait for the owner's OK. Ask with ask_owner (say what you will change; give an option with approve: true such as \"Yes, go ahead\"), then make the change after they approve.": "ยังไม่ได้ทำ: Mnemo อยู่ในโหมดถามก่อน การเปลี่ยนแปลงต้องรอเจ้าของอนุมัติ ถามด้วย ask_owner (บอกว่าจะเปลี่ยนอะไร ให้ตัวเลือกพร้อม approve: true เช่น \"ได้ เริ่มเลย\") แล้วค่อยเปลี่ยนหลังเขาอนุมัติ",
  "Not done: Mnemo is in Read only mode, so notes are not changed. Say what you would change; the owner can switch to Ask first or Auto in the chat.": "ยังไม่ได้ทำ: Mnemo อยู่ในโหมดอ่านอย่างเดียว จึงไม่แก้โน้ต บอกว่าจะเปลี่ยนอะไร เจ้าของสลับเป็นถามก่อนหรืออัตโนมัติได้ในแชต",
  "Not done: the chat is in Ask first mode, so a sub-agent cannot change notes. Say in your answer what should change; Mnemo asks the owner.": "ยังไม่ได้ทำ: แชตอยู่ในโหมดถามก่อน เอเจนต์ย่อยจึงแก้โน้ตไม่ได้ บอกในคำตอบว่าควรเปลี่ยนอะไร Mnemo จะถามเจ้าของ",
