  "On the Boards page each board has a ⋯ menu to open, rename, move, duplicate, colour or trash it. Right-click or a long press opens it too.": "ในหน้าบอร์ด แต่ละบอร์ดมีเมนู ⋯ สำหรับเปิด เปลี่ยนชื่อ ย้าย ทำสำเนา เปลี่ยนสี หรือย้ายไปถังขยะ คลิกขวาหรือกดค้างก็เปิดเมนูได้เช่นกัน",
  "On this page": "ในหน้านี้",
  "On: tap to switch off": "เปิด: แตะเพื่อปิด",
  "On: {mnemo} notes what it picks up in chats. Off: only what you add here. Saved at once.": "เปิด: {mnemo} จดสิ่งที่รับรู้ในแชต ปิด: เฉพาะสิ่งที่คุณเพิ่มที่นี่ บันทึกทันที",
  "Once installed, the app has its own icon, opens full screen and stays reachable when the network drops.": "เมื่อติดตั้งแล้ว แอปจะมีไอคอนของตัวเอง เปิดเต็มจอ และยังเข้าถึงได้แม้เครือข่ายหลุด",
  "Once it is connected, paste this into a new chat in that app. It tells the AI to store what it knows into Memora.": "เมื่อเชื่อมต่อแล้ว วางสิ่งนี้ในแชตใหม่ในแอปนั้น มันบอกให้ AI เก็บสิ่งที่รู้ลง Memora",
  "Once its app is set up, every call shows up here as it happens.": "เมื่อตั้งค่าแอปแล้ว ทุกการเรียกจะแสดงที่นี่ทันทีที่เกิดขึ้น",
  "Once {name} is connected, everything it reads, writes and searches shows up here, live.": "เมื่อ {name} เชื่อมต่อแล้ว ทุกอย่างที่มันอ่าน เขียน และค้นหาจะแสดงที่นี่แบบสด",
  "One address": "ที่อยู่เดียว",
  "One agent per app or device: its own key, its own name in Activity, turned off on its own.": "หนึ่งเอเจนต์ต่อหนึ่งแอปหรืออุปกรณ์: มีคีย์ของตัวเอง ชื่อของตัวเองใน กิจกรรม ปิดทีละตัวได้",
  "One click": "คลิกเดียว",
  "One device or connection, such as 203.0.113.7. Searching \"what is my IP\" shows yours.": "อุปกรณ์หรือการเชื่อมต่อเดียว เช่น 203.0.113.7 ค้นหา \"what is my IP\" จะเห็นของคุณ",
  "One device or connection.": "อุปกรณ์หรือการเชื่อมต่อเดียว",
  "One folder of notes that you and every connected AI share.": "โฟลเดอร์โน้ตเดียวที่คุณและ AI ที่เชื่อมต่อทุกตัวใช้ร่วมกัน",
  "One is hidden by the folder rule.": "หนึ่งรายการถูกซ่อนโดยกฎโฟลเดอร์",
  "One key per agent, its own permissions.": "หนึ่งคีย์ต่อเอเจนต์ พร้อมสิทธิ์ของตัวเอง",
  "One last step": "ขั้นตอนสุดท้าย",
  "One memory every agent reads and writes, and you can see, edit and connect all of it.": "หนึ่งความจำที่เอเจนต์ทุกตัวอ่านและเขียน และคุณดู แก้ไข และเชื่อมต่อทั้งหมดได้",
  "One memory for every AI": "ความจำเดียวสำหรับทุก AI",
  "One note shows this image; it will show as missing there. The version history keeps it.": "มีโน้ตหนึ่งแสดงรูปนี้ ที่นั่นจะแสดงว่าหายไป ประวัติเวอร์ชันเก็บไว้",
  "One per line. They show among the suggestions on a new chat, marked Yours, and stay until you change them.": "หนึ่งรายการต่อบรรทัด จะแสดงในคำแนะนำของแชตใหม่ ทำเครื่องหมาย ของคุณ และอยู่จนกว่าคุณจะเปลี่ยน",
  "One private memory that you and your AI apps share, so nothing has to be explained twice.": "ความจำส่วนตัวหนึ่งเดียวที่คุณและแอป AI ใช้ร่วมกัน ไม่ต้องอธิบายซ้ำสองรอบ",
  "One set of notes for every AI app": "โน้ตชุดเดียวสำหรับทุกแอป AI",
  "One thin progress bar instead of stark lane bars, softer shadows, lane colours across the whole lane, and overdue shown as a stroke.": "แถบความคืบหน้าบางเส้นเดียวแทนแถบเลนที่ดูแข็ง เงาที่นุ่มขึ้น สีเลนทั่วทั้งเลน และงานเกินกำหนดแสดงเป็นเส้นขีด",
  "Online": "ออนไลน์",
  "Only PNG, JPEG, WebP and GIF images can be added": "เพิ่มได้เฉพาะรูปภาพ PNG, JPEG, WebP และ GIF",
  "Only in the current version": "เฉพาะในเวอร์ชันปัจจุบัน",
  "Only in version {n}": "เฉพาะในเวอร์ชัน {n}",
  "Only letters, digits and - _ / . can be used.": "ใช้ได้เฉพาะตัวอักษร ตัวเลข และ - _ / .",
  "Only looks at notes; changes nothing.": "ดูโน้ตอย่างเดียว ไม่เปลี่ยนอะไร",
  "Only looks things up and never writes. For agents with a read-only key.": "ค้นหาอย่างเดียว ไม่เขียน สำหรับเอเจนต์ที่มีคีย์อ่านอย่างเดียว",
  "Only pictures in your newest message go to the image model, and you hear of it in a short toast.": "มีเพียงรูปในข้อความล่าสุดของคุณที่ส่งไปยังโมเดลรูปภาพ และแจ้งให้ทราบผ่านข้อความสั้น ๆ",
  "Only reads and answers; never changes notes": "อ่านและตอบเท่านั้น ไม่แก้ไขโน้ต",
  "Only the agents you pick. New agents can’t see it.": "เฉพาะเอเจนต์ที่คุณเลือก เอเจนต์ใหม่จะเห็นไม่ได้",
  "Only the first rule that fits a request counts.": "นับเฉพาะกฎแรกที่ตรงกับคำขอ",
  "Only the latest questions go on the page at first; earlier ones come in as you scroll up or jump to them on the timeline.": "ตอนแรกแสดงเฉพาะคำถามล่าสุด ส่วนที่เก่ากว่าจะมาเมื่อเลื่อนขึ้นหรือข้ามไปจากไทม์ไลน์",
