  "Password saved. Sign in with the new password.": "บันทึกรหัสผ่านแล้ว ลงชื่อเข้าใช้ด้วยรหัสผ่านใหม่",
  "Passwords are reset on the server that runs Memora.": "รหัสผ่านถูกรีเซ็ตบนเซิร์ฟเวอร์ที่รัน Memora",
