  "Past activity keeps the old name; new activity uses this one.": "กิจกรรมที่ผ่านมาคงชื่อเดิม กิจกรรมใหม่ใช้ชื่อนี้",
  "Past due dates show in a warning tint and today’s in a softer one, and the Boards page counts what is overdue. A board’s own date colours win.": "วันที่เลยกำหนดแสดงเป็นสีเตือน ส่วนวันนี้เป็นสีอ่อนกว่า และหน้าบอร์ดจะนับรายการที่เลยกำหนด สีวันที่ของบอร์ดเองมีความสำคัญกว่า",
  "Paste both into the app and save.": "วางทั้งสองในแอปแล้วบันทึก",
  "Paste it in a terminal and press <kbd>Enter</kbd>, then start Codex in that same terminal.": "วางในเทอร์มินัลแล้วกด <kbd>Enter</kbd> จากนั้นเริ่ม Codex ในเทอร์มินัลเดียวกัน",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Claude Code, or restart it: Memora loads by itself.": "วางในเทอร์มินัลแล้วกด <kbd>Enter</kbd> จากนั้นเริ่ม Claude Code หรือรีสตาร์ท: Memora จะโหลดเอง",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Gemini CLI, or restart it, and type <code>/mcp</code> to see Memora.": "วางในเทอร์มินัลแล้วกด <kbd>Enter</kbd> จากนั้นเริ่ม Gemini CLI หรือรีสตาร์ท แล้วพิมพ์ <code>/mcp</code> เพื่อดู Memora",
  "Paste it into the app where it asks for a key.": "วางลงในแอปที่ถามหาคีย์",
  "Paste it into the file and save, then press <b>Refresh</b>. Memora shows up in the list.": "วางลงในไฟล์แล้วบันทึก จากนั้นกด <b>รีเฟรช</b> Memora จะแสดงในรายการ",
  "Paste it into the file, save, and restart Claude Desktop. It needs Node.js on this computer.": "วางลงในไฟล์ บันทึก แล้วรีสตาร์ท Claude Desktop ต้องมี Node.js บนคอมพิวเตอร์นี้",
