  "Paste these once where {app} reads its standing instructions, so it uses Memora in every conversation, not only when asked.": "วางสิ่งเหล่านี้ครั้งเดียวที่ที่ {app} อ่านคำสั่งประจำ เพื่อให้ใช้ Memora ในทุกการสนทนา ไม่ใช่เมื่อถูกขอเท่านั้น",
