  "Save into Memora what I've shared with you about my personal life: my interests, habits, goals, the people who matter to me and things I care about. Put these notes in a folder named Private, one note per topic, and link related notes. Never save passwords, card numbers or other secrets. When you're done, tell me what you saved.": "บันทึกลง Memora สิ่งที่ฉันเล่าให้คุณฟังเกี่ยวกับชีวิตส่วนตัว: ความสนใจ นิสัย เป้าหมาย คนที่สำคัญกับฉัน และสิ่งที่ฉันใส่ใจ เก็บโน้ตเหล่านี้ในโฟลเดอร์ชื่อ Private หนึ่งโน้ตต่อหนึ่งหัวข้อ และเชื่อมโน้ตที่เกี่ยวข้องกัน ห้ามบันทึกรหัสผ่าน หมายเลขบัตร หรือความลับอื่น เมื่อเสร็จ บอกฉันว่าบันทึกอะไร",
