  "Switch": "สลับ",
  "Switch back to {path}": "สลับกลับไป {path}",
  "Switch read and edit": "สลับอ่านและแก้ไข",
  "Switch the model for this chat?": "สลับโมเดลของแชตนี้ไหม",
