  "Switch tools off for Mnemo or for its sub-agents, and keep notes, folders or pictures private from it.": "ปิดเครื่องมือสำหรับ Mnemo หรือเอเจนต์ย่อยของมัน และเก็บโน้ต โฟลเดอร์ หรือรูปภาพเป็นส่วนตัวจากมัน",
  "Switch tools on or off for everyone and change any agent's key and access, its own included.": "เปิดหรือปิดเครื่องมือสำหรับทุกคนและเปลี่ยนคีย์และการเข้าถึงของเอเจนต์ใดก็ได้ รวมถึงของตัวเอง",
  "Switch {agent}'s model": "สลับโมเดลของ {agent}",
  "Switch {agent}'s model?": "สลับโมเดลของ {agent} ไหม",
  "Switched off for every agent on the server": "ปิดสำหรับเอเจนต์ทุกตัวบนเซิร์ฟเวอร์",
  "Switched on": "เปิดแล้ว",
  "Switched to {model}": "สลับเป็น {model} แล้ว",
  "Switches": "สวิตช์",
  "Switches and the tool list": "สวิตช์และรายการเครื่องมือ",
  "Switches {n} tool back on for every AI.": "เปิดเครื่องมือ {n} รายการกลับสำหรับ AI ทุกตัว",
  "Switches {n} tools back on for every AI.": "เปิดเครื่องมือ {n} รายการกลับสำหรับ AI ทุกตัว",
  "System": "ระบบ",
  "System lines shown": "แสดงบรรทัดของระบบ",
  "Tab or click to filter by it": "Tab หรือคลิกเพื่อกรองด้วยมัน",
  "Tab to filter · click to go there": "Tab เพื่อกรอง · คลิกเพื่อไปที่นั่น",
  "Tag": "แท็ก",
  "Tag list cleared. It is rebuilt the next time tags are used.": "ล้างรายการแท็กแล้ว จะสร้างใหม่เมื่อใช้แท็กครั้งถัดไป",
  "Tag my reading notes and link them to the launch plan.": "แท็กโน้ตการอ่านของฉันและเชื่อมกับแผนเปิดตัว",
  "Tag suggestions": "คำแนะนำแท็ก",
  "Tagged #{tag}": "ติดแท็ก #{tag} แล้ว",
  "Tags": "แท็ก",
  "Tags matching “{q}”": "แท็กที่ตรงกับ “{q}”",
  "Tags on cards": "แท็กบนการ์ด",
  "Task": "งาน",
  "Tasks, checks and pins": "งาน การตรวจ และหมุด",
