  "This browser cannot show notifications.": "เบราว์เซอร์นี้แสดงการแจ้งเตือนไม่ได้",
  "This can no longer be undone: the note has changed since.": "เลิกทำไม่ได้อีกแล้ว: โน้ตเปลี่ยนไปแล้วตั้งแต่นั้น",
  "This chat": "แชตนี้",
  "This chat keeps everything from its first message to the last for this model. Near {n} tokens {mnemo} folds the older messages into a summary and carries on.": "แชตนี้เก็บทุกอย่างตั้งแต่ข้อความแรกถึงล่าสุดสำหรับโมเดลนี้ เมื่อใกล้ {n} โทเค็น {mnemo} จะย่อข้อความเก่าเป็นสรุปแล้วทำต่อ",
  "This chat so far was answered by {prev}. From the next message on, {model} answers, with the whole chat as context. Its answers may read a little differently, and its memory for this chat may be smaller or larger.": "แชตนี้จนถึงตอนนี้ตอบโดย {prev} ตั้งแต่ข้อความถัดไป {model} จะตอบ โดยมีทั้งแชตเป็นบริบท คำตอบอาจอ่านต่างไปเล็กน้อย และความจำของมันสำหรับแชตนี้อาจเล็กหรือใหญ่กว่า",
  "This chat so far was answered by {prev}. From the next message on, {model} answers, with the whole chat as context. Its answers may read a little differently.": "แชตนี้จนถึงตอนนี้ตอบโดย {prev} ตั้งแต่ข้อความถัดไป {model} จะตอบ โดยมีทั้งแชตเป็นบริบท คำตอบอาจอ่านต่างไปเล็กน้อย",
  "This chat · hidden": "แชตนี้ · ซ่อน",
