  "This computer, your network or the internet": "คอมพิวเตอร์เครื่องนี้ เครือข่ายของคุณ หรืออินเทอร์เน็ต",
  "This connection request cannot be used": "ใช้คำขอเชื่อมต่อนี้ไม่ได้",
