  "This note has no headings yet.": "โน้ตนี้ยังไม่มีหัวข้อ",
  "This note has not been saved to the history yet. The next change starts it.": "โน้ตนี้ยังไม่ถูกบันทึกลงประวัติ การเปลี่ยนแปลงครั้งถัดไปจะเริ่มต้นมัน",
