  "This note is removed from the vault for good, with its text, tags and links. Every earlier version is erased from the version history too, so no one, agents included, can read it again.": "โน้ตนี้จะถูกลบออกจากคลังถาวร พร้อมข้อความ แท็ก และลิงก์ ทุกเวอร์ชันก่อนหน้าจะถูกลบจากประวัติเวอร์ชันด้วย ทำให้ไม่มีใคร รวมถึงเอเจนต์ อ่านได้อีก",
