  "This server is run by systemd, which starts it again a few seconds later. To keep it stopped, run {cmd} on the server instead.": "เซิร์ฟเวอร์นี้ถูกรันโดย systemd ซึ่งจะเริ่มใหม่อีกไม่กี่วินาที หากต้องการให้หยุดต่อ ให้รัน {cmd} บนเซิร์ฟเวอร์แทน",
  "This server runs in Docker, which may start it again. To keep it stopped, run {cmd} on the host instead.": "เซิร์ฟเวอร์นี้รันใน Docker ซึ่งอาจเริ่มใหม่ หากต้องการให้หยุดต่อ ให้รัน {cmd} บนโฮสต์แทน",
  "This vault has no tags yet. Add {inline} or a {line} line to a note.": "คลังนี้ยังไม่มีแท็ก เพิ่ม {inline} หรือบรรทัด {line} ในโน้ต",
