  "Too many wrong codes, so this setup code no longer works. Run memora-cli setup on the server for a new one.": "ใส่รหัสผิดหลายครั้งเกินไป รหัสตั้งค่านี้จึงใช้ไม่ได้อีก รัน memora-cli setup บนเซิร์ฟเวอร์เพื่อรับรหัสใหม่",
