  "{mnemo} asks before sub-agents run": "{mnemo} ถามก่อนเอเจนต์ย่อยทำงาน",
  "{mnemo} asks this model when you want a picture made.": "{mnemo} ถามโมเดลนี้เมื่อคุณต้องการให้สร้างรูปภาพ",
  "{mnemo} button hidden. Bring it back from More, Show the {mnemo} button.": "ซ่อนปุ่ม {mnemo} แล้ว นำกลับจาก เพิ่มเติม แสดงปุ่ม {mnemo}",
  "{mnemo} button hidden. Show it again here or from More.": "ซ่อนปุ่ม {mnemo} แล้ว แสดงอีกครั้งที่นี่หรือจาก เพิ่มเติม",
  "{mnemo} could not write new ones just now. Check the model in Settings.": "{mnemo} เขียนใหม่ไม่ได้ในตอนนี้ ตรวจโมเดลในการตั้งค่า",
  "{mnemo} hands pictures to this model when the chat model cannot see.": "{mnemo} ส่งรูปภาพให้โมเดลนี้เมื่อโมเดลแชตมองไม่เห็น",
  "{mnemo} is working on this": "{mnemo} กำลังทำงานเรื่องนี้",
  "{mnemo} keeps only what you add": "{mnemo} เก็บเฉพาะที่คุณเพิ่ม",
  "{mnemo} knows nothing about you yet.": "{mnemo} ยังไม่รู้อะไรเกี่ยวกับคุณ",
  "{mnemo} looks after your notes": "{mnemo} ดูแลโน้ตของคุณ",
  "{mnemo} may learn about you": "{mnemo} เรียนรู้เกี่ยวกับคุณได้",
  "{mnemo} only works in your notes. Each change shows in Activity and can be undone from History.": "{mnemo} ทำงานเฉพาะในโน้ตของคุณ ทุกการเปลี่ยนแปลงแสดงใน กิจกรรม และเลิกทำได้จาก ประวัติ",
  "{mnemo} reads your vault in a new chat and keeps what it learns here.": "{mnemo} อ่านคลังของคุณในแชตใหม่ และเก็บสิ่งที่เรียนรู้ไว้ที่นี่",
  "{mnemo} settings saved": "บันทึกการตั้งค่า {mnemo} แล้ว",
  "{mnemo} settings: models and keys": "การตั้งค่า {mnemo}: โมเดลและคีย์",
  "{mnemo} starts sub-agents by itself when a task splits well; there is nothing to set up. They run on your default model, then the fallbacks, unless you name a model in the chat. Follow them, and switch their model, in Agents at the top right of the chat. They use tokens of their own, so in Ask first {mnemo} asks and says roughly how many; in Auto they just run. Saved at once.": "{mnemo} เริ่มเอเจนต์ย่อยเองเมื่องานแยกได้ดี ไม่ต้องตั้งค่าอะไร พวกมันใช้โมเดลเริ่มต้นของคุณ แล้วโมเดลสำรอง เว้นแต่คุณระบุโมเดลในแชต ติดตามและสลับโมเดลของพวกมันได้ใน เอเจนต์ ที่มุมขวาบนของแชต พวกมันใช้โทเค็นของตัวเอง ดังนั้นใน ถามก่อน {mnemo} จะถามและบอกจำนวนคร่าวๆ ใน อัตโนมัติ พวกมันรันเลย บันทึกทันที",
  "{mnemo} stopped it": "{mnemo} หยุดมันแล้ว",
  "{mnemo} will keep that in mind": "{mnemo} จะจำเรื่องนั้นไว้",
  "{mnemo} writes new suggestions from your recent notes (yours stay)": "{mnemo} เขียนคำแนะนำใหม่จากโน้ตล่าสุดของคุณ (ของคุณยังอยู่)",
  "{mnemo}'s own ({n})": "ของ {mnemo} เอง ({n})",
  "{mnemo}'s own notes on how to talk to you, read in every chat. Click one to change it.": "โน้ตของ {mnemo} เองเกี่ยวกับวิธีพูดกับคุณ อ่านในทุกแชต คลิกเพื่อเปลี่ยน",
  "{mnemo}, your notes agent": "{mnemo} เอเจนต์โน้ตของคุณ",
  "{mnemo}: {text}": "{mnemo}: {text}",
  "{model} cannot look at images; it got their names instead. Set a model that reads images in Settings to have them seen.": "{model} ดูรูปภาพไม่ได้ จึงได้รับแค่ชื่อไฟล์ ตั้งโมเดลที่อ่านรูปภาพได้ในการตั้งค่าเพื่อให้ดูรูปได้",
  "{model} cannot look at images; the image model described them for it.": "{model} ดูรูปภาพไม่ได้ โมเดลรูปภาพจึงบรรยายให้แทน",
  "{model} cannot read pictures, so it only gets their names. Set a model that reads images, or switch this chat's model.": "{model} อ่านรูปภาพไม่ได้ จึงได้รับแค่ชื่อไฟล์ ตั้งโมเดลที่อ่านรูปภาพได้ หรือเปลี่ยนโมเดลของแชตนี้",
  "{model} cannot read pictures, so it only got their names. Set a model that reads images, or switch this chat's model.": "{model} อ่านรูปภาพไม่ได้ จึงได้รับแค่ชื่อไฟล์ ตั้งโมเดลที่อ่านรูปภาพได้ หรือเปลี่ยนโมเดลของแชตนี้",
  "{model} cannot read pictures, so the image model looked at them for it.": "{model} อ่านรูปภาพไม่ได้ โมเดลรูปภาพจึงดูให้แทน",
  "{model} cannot read pictures, so the image model looks at them for it.": "{model} อ่านรูปภาพไม่ได้ โมเดลรูปภาพจึงกำลังดูให้แทน",
  "{model} did not answer ({why}); trying again in {wait} s ({n}/{total})…": "{model} ไม่ตอบ ({why}) กำลังลองใหม่ใน {wait} วินาที ({n}/{total})…",
  "{model} is answering": "{model} กำลังตอบ",
