  "{model} takes over from {agent}'s next step (it is working now), and answers its follow-ups in this chat. It may work a little differently from {prev}.": "{model} เข้ามาแทน {agent} ตั้งแต่ขั้นตอนถัดไป (กำลังทำงานอยู่) และตอบการติดตามผลในแชตนี้ อาจทำงานต่างจาก {prev} เล็กน้อย",
  "{model} takes over from {agent}'s next step, and answers its follow-ups in this chat. It may work a little differently from {prev}.": "{model} เข้ามาแทน {agent} ตั้งแต่ขั้นตอนถัดไป และตอบการติดตามผลในแชตนี้ อาจทำงานต่างจาก {prev} เล็กน้อย",
